<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {roles} from '../data/overview'
import {getImportStatus,type ImportStatus} from '../api/client'
import UiButton from '../components/UiButton.vue'
const props=defineProps<{role:string}>()
const paths:Record<string,string>={leadership:'/leadership',specialist:'/specialist',planning:'/planning'}
const current=computed(()=>roles.find(r=>r.to===paths[props.role]))
const status=ref<ImportStatus>(),loading=ref(false),error=ref('')
let controller:AbortController|undefined
async function load(){controller?.abort();controller=new AbortController();const local=controller;loading.value=true;error.value='';try{const result=await getImportStatus(local.signal);if(!local.signal.aborted)status.value=result}catch(e){if(!local.signal.aborted)error.value=e instanceof Error?e.message:'无法读取数据'}finally{if(!local.signal.aborted)loading.value=false}}
onMounted(()=>{if(current.value)load()});watch(()=>props.role,()=>{status.value=undefined;if(current.value)load();else controller?.abort()});onBeforeUnmount(()=>controller?.abort())
</script>
<template><section class="workspace-page"><template v-if="current"><div class="workspace-heading"><div><span class="mono">{{current.english}}</span><h1>{{current.title}}</h1><p>{{current.description}}</p></div><RouterLink to="/" class="action action-light">返回总览</RouterLink></div><div class="workspace-grid"><section class="workspace-surface"><h2>数据连接</h2><p v-if="loading" role="status">正在读取数据服务…</p><div v-else-if="error" role="alert"><p>{{error}}</p><p class="connection-hint">请确认本地数据服务已在 8000 端口启动。</p><UiButton label="重新连接" @click="load"/></div><dl v-else-if="status"><div><dt>企业</dt><dd>{{status.enterprise_count}}</dd></div><div><dt>政策</dt><dd>{{status.policy_count}}</dd></div><div><dt>产业环节</dt><dd>{{status.segment_count}}</dd></div></dl></section><section class="workspace-surface"><h2>本视图工作范围</h2><ul><li v-for="detail in current.details" :key="detail">{{detail}}</li></ul><p class="connection-hint">页面框架已就绪，业务模块待接入。</p></section></div></template><template v-else><h1>页面未找到</h1><RouterLink to="/" class="action action-light">返回总览</RouterLink></template></section></template>
<style scoped>.workspace-page{min-height:calc(100svh - 64px);padding:140px max(var(--page-gutter),5vw) 64px}.workspace-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:64px}.workspace-heading .mono{color:var(--color-muted)}h1{font-size:clamp(32px,4vw,52px);margin:12px 0 20px}.workspace-heading p{color:var(--color-muted)}.workspace-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.workspace-surface{background:var(--color-surface);padding:32px;min-height:250px}.workspace-surface h2{font-size:var(--text-card);margin-bottom:32px}.workspace-surface dl{display:flex;justify-content:space-between;gap:20px}.workspace-surface dt{color:var(--color-muted)}.workspace-surface dd{margin:12px 0 0;font-size:36px;font-variant-numeric:tabular-nums}.workspace-surface ul{padding-left:20px;line-height:2.2}.connection-hint{color:var(--color-muted);font-size:var(--text-xs);margin:16px 0 24px}@media(max-width:700px){.workspace-heading{align-items:start;flex-direction:column}.workspace-grid{grid-template-columns:1fr}.workspace-surface{padding:24px}}</style>
